    /** 语言选择页的代码表（顺序即展示顺序，"system" 恒为第一项）。 */
    public static final String[] CODES = {"system","zh","zh_TW","en","ja","ko","de","fr","es","ru","pt","it","ar","az","bg","bn","bs","ca","cs","da","el","et","eu","fa","fi","fil","he","hi","hr","hu","id","is","lt","lv","mk","ms","nb","ne","nl","pl","ro","sk","sl","sq","sr","sv","sw","th","tr","uk","ur","uz","vi"};
    /** 各语言的自称（第一项由 follow_system 词条替换）。 */
    public static final String[] LABELS = {"system","简体中文","繁體中文","English","日本語","한국어","Deutsch","Français","Español","Русский","Português","Italiano","العربية","Azərbaycan","Български","বাংলা","Bosanski","Català","Čeština","Dansk","Ελληνικά","Eesti","Euskara","فارسی","Suomi","Filipino","עברית","हिन्दी","Hrvatski","Magyar","Bahasa Indonesia","Íslenska","Lietuvių","Latviešu","Македонски","Bahasa Melayu","Norsk bokmål","नेपाली","Nederlands","Polski","Română","Slovenčina","Slovenščina","Shqip","Српски","Svenska","Kiswahili","ไทย","Türkçe","Українська","اردو","Oʻzbekcha","Tiếng Việt"};

    public static int langCount() { return CODES.length; }
    public static String codeAt(int i) { return CODES[i]; }
    public static String labelAt(int i) { return i == 0 ? get("follow_system") : LABELS[i]; }

    /** 系统 Locale 的 language 代码归一化到我们的 code（iw/in/tl/no 这类历史代码要换算）。 */
    private static String normalizeCode(String lang) {
        if (lang == null) return "en";
        if ("iw".equals(lang)) return "he";
        if ("in".equals(lang)) return "id";
        if ("tl".equals(lang)) return "fil";
        if ("no".equals(lang)) return "nb";
        if ("zh".equals(lang)) return "zh";
        return dict.containsKey(lang) ? lang : "en";
    }

    public static void init(Context ctx) {
        String lang = ctx.getSharedPreferences("oldsend", Context.MODE_PRIVATE).getString("app_lang", "system");
        if ("system".equals(lang)) {
            String sysLang = Locale.getDefault().getLanguage();
            String sysCountry = Locale.getDefault().getCountry();
            if ("zh".equals(sysLang)) {
                currentLang = "TW".equals(sysCountry) || "HK".equals(sysCountry) ? "zh_TW" : "zh";
            } else {
                currentLang = normalizeCode(sysLang);
            }
        } else {
            currentLang = lang;
        }
    }

    /** 当前生效的语言代码（zh / zh_TW / en / ja ...），供随语言变化的文案使用。 */
    public static String current() { return currentLang; }

        // 扩展语言包：继承英文全量，覆盖最常用界面文案；未覆盖的长尾词条自动回退英文，
